static void uss720_disconnect ( struct usb_interface * intf ) { struct parport * pp = usb_get_intfdata ( intf ) ; struct parport_uss720_private * priv ; dev_dbg ( & intf -> dev , "disconnect\n" ) ; usb_set_intfdata ( intf , NULL ) ; if ( pp ) { priv = pp -> private_data ; priv -> pp = NULL ; dev_dbg ( & intf -> dev , "parport_remove_port\n" ) ; parport_remove_port ( pp ) ; parport_put_port ( pp ) ; kill_all_async_requests_priv ( priv ) ; } dev_dbg ( & intf -> dev , "disconnect done\n" ) ; } 